// Interface defined in service layer (high-level module owns this)
public interface UserRepository {
    Optional<User> findById(Long id);
    void save(User user);
}

// Implementation in repository layer (low-level module implements interface)
@Repository
public class JpaUserRepository implements UserRepository {
    public Optional<User> findById(Long id) {
        // JPA logic to query database
        return Optional.of(new User(id, "Alice"));
    }
    public void save(User user) { /* persist to DB */ }
}

// High-level service depends on interface only
@Service
public class UserService {
    private final UserRepository userRepository; // interface type, not JpaUserRepository

    // Constructor injection - Spring provides the implementation
    public UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    public User registerUser(Long id) {
        var user = userRepository.findById(id).orElseThrow();
        // business logic here
        userRepository.save(user);
        return user; // UserService never knows about JpaUserRepository
    }
}

// WRONG: OrderService creates its own dependency
@Service
public class OrderService {
    public void processOrder(Long orderId) {
        // Hard dependency on concrete MySQLOrderRepository
        var repository = new MySQLOrderRepository(); // DIP violation
        var order = repository.findById(orderId);
        // business logic
        repository.save(order);
    }
}

// RIGHT: OrderService depends on abstraction, receives implementation
@Service
public class OrderService {
    private final OrderRepository repository; // interface

    // Dependency injected via constructor
    public OrderService(OrderRepository repository) {
        this.repository = repository; // no new keyword
    }

    public void processOrder(Long orderId) {
        var order = repository.findById(orderId); // works with any implementation
        // business logic
        repository.save(order);
        // Value objects are fine to create with new
        var timestamp = LocalDateTime.now(); // not a DIP violation
        var items = List.of("item1", "item2"); // not a DIP violation
    }
}

// High-level module defines the abstraction it needs
public interface OrderRepository {
    Order findById(Long id);
    void save(Order order);
}

// Low-level module depends on the abstraction (implements it)
@Repository
public class MySQLOrderRepository implements OrderRepository {
    public Order findById(Long id) {
        // JDBC or JPA code to query MySQL
        return new Order(id, "Sample Item");
    }
    public void save(Order order) { /* persist to MySQL */ }
}

// High-level business logic depends on abstraction, not concrete class
@Service
public class OrderService {
    private final OrderRepository repository; // interface, not MySQLOrderRepository

    public OrderService(OrderRepository repository) {
        this.repository = repository; // Spring injects concrete implementation
    }

    public Order processOrder(Long orderId) {
        var order = repository.findById(orderId); // works with any implementation
        // business logic here
        repository.save(order);
        return order;
    }
}

