// DIP (the principle): high-level OrderService depends on an ABSTRACTION
interface PaymentGateway { void charge(double amount); }

class OrderService {
    private final PaymentGateway gateway; // the interface, not Stripe directly
    // DI (the technique): the dependency is supplied from outside
    OrderService(PaymentGateway gateway) { this.gateway = gateway; }
    void checkout(double total) { gateway.charge(total); }
}

class StripeGateway implements PaymentGateway {
    public void charge(double amount) { /* call Stripe */ }
}

// DI in action (Spring's IoC container does this for you):
OrderService service = new OrderService(new StripeGateway());
```
DIP says 'depend on the interface'; DI is how that interface gets handed in.

// Production code follows DIP
@Service
public class OrderService {
    private final OrderRepository repository;

    public OrderService(OrderRepository repository) {
        this.repository = repository;
    }

    public Order processOrder(Long orderId) {
        var order = repository.findById(orderId)
            .orElseThrow(() -> new OrderNotFoundException(orderId));
        order.markAsProcessed();
        repository.save(order);
        return order;
    }
}

// Unit test injects mock implementation
class OrderServiceTest {
    @Test
    void shouldProcessOrderWhenFound() {
        // Create mock that implements the interface
        var mockRepo = Mockito.mock(OrderRepository.class);
        var testOrder = new Order(1L, "Test Item");
        Mockito.when(mockRepo.findById(1L)).thenReturn(Optional.of(testOrder));

        var service = new OrderService(mockRepo); // inject mock
        var result = service.processOrder(1L);

        assertEquals("Test Item", result.item());
        Mockito.verify(mockRepo).save(testOrder); // verify save was called
        // Test runs in milliseconds—no database needed
    }
}
